#include "pypto/codegen/code_emitter.h"

#include <cstddef>
#include <string>

#include "pypto/core/logging.h"

namespace pypto {

namespace codegen {

void CodeEmitter::EmitLine(const std::string& line) {
  if (!line.empty()) {
    buffer_ << GetIndent() << line;
  }
  buffer_ << "\n";
}

void CodeEmitter::IncreaseIndent() { indent_level_++; }

void CodeEmitter::DecreaseIndent() {
  INTERNAL_CHECK(indent_level_ > 0) << "Internal error: cannot decrease indent level below 0";
  indent_level_--;
}

std::string CodeEmitter::GetCode() const { return buffer_.str(); }

void CodeEmitter::AppendRaw(const std::string& text) { buffer_ << text; }

std::string CodeEmitter::GetIndentString() const { return GetIndent(); }

int CodeEmitter::GetIndentLevel() const { return indent_level_; }

void CodeEmitter::SetIndentLevel(int level) {
  INTERNAL_CHECK(level >= 0) << "Internal error: indentation level cannot be negative";
  indent_level_ = level;
}

void CodeEmitter::Clear() {
  buffer_.str("");
  buffer_.clear();
  indent_level_ = 0;
}

std::string CodeEmitter::GetIndent() const {
  return std::string(static_cast<size_t>(indent_level_ * kIndentSpaces), ' ');
}

}  // namespace codegen

}  // namespace pypto

