87	// this name reserved in modules that use deferred completion so a user kernel
88	// cannot silently collide with the private adapter declaration.
89	constexpr const char* kDeferredCompletionAdapterName = "pypto_register_counter_completion";
90	
91	// Escape a source path for an MLIR `"..."` string literal. A path is an
92	// arbitrary OS byte string — on POSIX every byte except `/` and NUL is legal, so
93	// a quote, a backslash, or a raw control character in one must not be able to
94	// break the module. MLIR's lexer accepts `\\`, `\"`, `\n`, `\t` and `\xx` hex
95	// escapes, and rejects an unescaped control character inside a literal, so
96	// anything outside printable ASCII is emitted as a hex escape.
97	std::string EscapeMlirString(const std::string& str) {
98	  static constexpr char kHexDigits[] = "0123456789ABCDEF";
99	  std::string escaped;
100	  escaped.reserve(str.size());
101	  for (char c : str) {
102	    const auto byte = static_cast<unsigned char>(c);
103	    if (c == '\\' || c == '"') {
104	      escaped.push_back('\\');
105	      escaped.push_back(c);
106	    } else if (c == '\n') {
107	      escaped += "\\n";
108	    } else if (c == '\t') {
109	      escaped += "\\t";
110	    } else if (byte < 0x20 || byte == 0x7F) {
111	      escaped += "\\";
112	      escaped.push_back(kHexDigits[byte >> 4]);
113	      escaped.push_back(kHexDigits[byte & 0x0F]);
114	    } else {
115	      escaped.push_back(c);
116	    }
117	  }
118	  return escaped;
119	}
120	
121	// True when `inner` is a source range nested inside `outer` — the invariant a
122	// sub-expression's span satisfies with respect to its enclosing statement's span.
123	//
124	// This is what rejects a Call span that a pass overwrote with a coarser one.
125	// ConvertTensorToTileOps rebuilds every tile op it synthesizes with the enclosing
126	// *function*'s span (convert_tensor_to_tile_ops_pass.cpp), which begins before the
127	// statement and therefore fails containment — so the statement's own span, which
128	// that rewrite preserved, is kept instead.
129	bool SpanContains(const ir::Span* outer, const ir::Span& inner) {
130	  if (!inner.is_valid() || inner.filename_.empty()) return false;
131	  // No usable enclosing span means nothing contradicts the inner one.
132	  if (outer == nullptr || !outer->is_valid() || outer->filename_.empty()) return true;
133	  if (outer->filename_ != inner.filename_) return false;
134	  // An unknown end line (-1) degenerates to a single-line range at the start.
135	  const int outer_end = outer->end_line_ > 0 ? outer->end_line_ : outer->begin_line_;
136	  const int inner_end = inner.end_line_ > 0 ? inner.end_line_ : inner.begin_line_;
137	  // Both ends must sit inside the statement. Checking only the start would accept
138	  // a rebuilt span that begins within the statement but runs past its last line,
139	  // which is exactly the untrustworthy case this predicate exists to reject.
140	  return inner.begin_line_ >= outer->begin_line_ && inner_end <= outer_end;
141	}
142	
143	// Full-MemRef-identity key used by PTOAS memory-planner codegen to decide when
144	// two tile variables denote the *same* buffer (and must share one tile_buf
145	// handle so the op writes in place). Same base + byte_offset + size = same
146	// buffer (loop-carried accumulator, in-place op result). A view shares the
147	// base but differs in offset and/or size, so it gets a distinct key.
148	std::string MemRefIdentityKey(const ir::MemRefPtr& memref) {
149	  std::ostringstream key;
150	  key << static_cast<const void*>(memref->base_.get()) << '|';
151	  if (auto off = As<ir::ConstInt>(memref->byte_offset_)) {
152	    key << "off" << off->value_;
153	  } else {
154	    key << "off@" << static_cast<const void*>(memref->byte_offset_.get());
155	  }
156	  key << "|sz" << memref->size_;
157	  return key.str();
158	}
