160	// Base Ptrs of tile phis — an `IfStmt` / `ForStmt` / `WhileStmt` return var, or a
161	// loop-carried iter_arg. Under the PTOAS planner those take a handle declared in
162	// the function head (see pto_control_flow_codegen.cpp), which a per-use
163	// `pto.multi_tile_get` cannot supply: a runtime slot index is not in scope there.
164	// An allocation whose slots feed one is therefore rejected, not degraded.
165	class TilePhiBaseCollector : public ir::IRVisitor {
166	 public:
167	  std::set<const ir::Var*> bases;
168	
169	  void VisitStmt_(const ir::IfStmtPtr& op) override {
170	    Record(op->return_vars_);
171	    ir::IRVisitor::VisitStmt_(op);
172	  }
173	
174	  void VisitStmt_(const ir::ForStmtPtr& op) override {
175	    Record(op->return_vars_);
176	    Record(op->iter_args_);
177	    ir::IRVisitor::VisitStmt_(op);
178	  }
179	
180	  void VisitStmt_(const ir::WhileStmtPtr& op) override {
181	    Record(op->return_vars_);
182	    Record(op->iter_args_);
183	    ir::IRVisitor::VisitStmt_(op);
184	  }
