186	 private:
187	  template <typename VarLikePtr>
188	  void Record(const std::vector<VarLikePtr>& vars) {
189	    for (const auto& var : vars) {
190	      if (!var) continue;
191	      auto tile_type = ir::GetTileTypeWithMemRef(var->GetType());
192	      if (!tile_type) continue;
193	      bases.insert(ir::GetDefinedMemRef(tile_type)->base_.get());
194	    }
195	  }
196	};
197	
198	// Allocations with two or more slots selected inside one loop body.
199	//
200	// ptoas derives the per-slot WAR guard from the slot expression, but only for the
201	// FIRST `multi_tile_get` of a region in an iteration: given two co-live slots it
202	// emits the dynamic `wait_flag`/`set_flag` pair for one and leaves the other load
203	// unguarded, so the next iteration's write into that slot races the current
204	// iteration's read of it. Measured on ptoas 0.54 (`--enable-insert-sync`,
205	// `--pto-level=level2`, a3) — the kernel is silently wrong on device, not slow.
206	// Filed as hw-native-sys/PTOAS#1118.
207	//
208	// The ping-pong the region form exists for takes ONE slot per iteration, and that
209	// shape is guarded correctly. So the co-live shape is rejected rather than
210	// miscompiled, and the author is pointed at the PyPTO planner, whose baked
211	// addresses and PyPTO-emitted sync handle it. Straight-line code is untouched:
212	// with no loop there is no cross-iteration reuse to guard.
213	class CoLiveSlotCollector : public ir::IRVisitor {
214	 public:
215	  std::set<const ir::Var*> bases;  ///< Allocations with >= 2 slots live in one loop body
216	
217	  void VisitStmt_(const ir::ForStmtPtr& op) override { VisitLoop(op); }
218	  void VisitStmt_(const ir::WhileStmtPtr& op) override { VisitLoop(op); }
219	
220	  void VisitStmt_(const ir::AssignStmtPtr& op) override {
221	    if (loop_depth_ > 0) {
222	      if (auto tile_type = ir::GetTileTypeWithMemRef(op->var_->GetType())) {
223	        const auto memref = ir::GetDefinedMemRef(tile_type);
224	        if (memref->slot_count_ > 1 && memref->slot_index_.has_value() && *memref->slot_index_) {
225	          // Second slot-selecting tile on this allocation in the same loop body.
226	          if (!per_loop_seen_.insert(memref->base_.get()).second) bases.insert(memref->base_.get());
227	        }
228	      }
229	    }
230	    ir::IRVisitor::VisitStmt_(op);
231	  }
232	
233	 private:
234	  template <typename LoopPtr>
235	  void VisitLoop(const LoopPtr& op) {
236	    // Each loop body counts on its own: two slots in *sibling* loops are never
237	    // live together, and a nested loop's own body is the iteration that matters.
238	    auto saved = std::move(per_loop_seen_);
239	    per_loop_seen_.clear();
240	    ++loop_depth_;
241	    ir::IRVisitor::VisitStmt_(op);
242	    --loop_depth_;
243	    per_loop_seen_ = std::move(saved);
244	  }
245	
246	  int loop_depth_ = 0;
247	  std::set<const ir::Var*> per_loop_seen_;
248	};
