253	// there is one, the physical shape otherwise — but as values rather than emitted
254	// SSA, because a multi-buffer region states ONE valid extent for all its slots and
255	// therefore has to compare them before declaring it. The tile_buf type string
256	// cannot stand in for this comparison: it deliberately renders `v_row=?, v_col=?`,
257	// so two slots differing only in valid_shape print identically.
258	std::optional<std::pair<int64_t, int64_t>> StaticValidExtents(
259	    const std::shared_ptr<const ir::TileType>& tile_type) {
260	  const std::vector<ir::ExprPtr>* dims = nullptr;

